implementation:
#include <linux/dcache.h>
#include <linux/xattr.h>
#include <linux/crypto.h>
#include <linux/hmac.h>
#include <linux/scatterlist.h>
#include <linux/err.h>

enum integrity_status {
    INTEGRITY_PASS = 0,
    INTEGRITY_FAIL,
    INTEGRITY_NO_ATTRIBUTE
}; 

struct integrity_iint_cache {
    enum integrity_status status;
}; 

enum integrity_status verify_hmac_xattr(struct dentry *dentry, const char *xattr_name, char *xattr_value, size_t xattr_value_len, struct integrity_iint_cache *iint) {
    enum integrity_status status = iint->status;

    if (status == INTEGRITY_PASS) {
        return status;
    }

    if (!dentry || !xattr_name || !xattr_value || !iint) {
        return INTEGRITY_FAIL;
    }

    if (xattr_value_len == 0) {
        return INTEGRITY_NO_ATTRIBUTE;
    }

    if (xattr_value_len > 4096) {
        return INTEGRITY_FAIL;
    }

    struct crypto_shash *tfm = crypto_alloc_shash("hmac(sha256)", 0, 0);
    if (IS_ERR(tfm)) {
        return INTEGRITY_FAIL;
    }

    struct shash_desc *desc = kmalloc(sizeof(*desc) + crypto_shash_descsize(tfm), GFP_KERNEL);
    if (!desc) {
        crypto_free_shash(tfm);
        return INTEGRITY_FAIL;
    }

    desc->tfm = tfm;

    int err = crypto_shash_init(desc);
    if (err) {
        kfree(desc);
        crypto_free_shash(tfm);
        return INTEGRITY_FAIL;
    }

    err = crypto_shash_update(desc, xattr_value, xattr_value_len);
    if (err) {
        kfree(desc);
        crypto_free_shash(tfm);
        return INTEGRITY_FAIL;
    }

    u8 digest[32];
    err = crypto_shash_final(desc, digest);
    if (err) {
        kfree(desc);
        crypto_free_shash(tfm);
        return INTEGRITY_FAIL;
    }

    kfree(desc);
    crypto_free_shash(tfm);

    if (memcmp(digest, xattr_value, 32) == 0) {
        iint->status = INTEGRITY_PASS;
        return INTEGRITY_PASS;
    } else {
        iint->status = INTEGRITY_FAIL;
        return INTEGRITY_FAIL;
    }
}
